1	import { useState } from "react";
2	import { useListPlayers, useCreatePlayer, useUpdatePlayer, useDeletePlayer, useAiEnhancePlayer, getListPlayersQueryKey } from "@workspace/api-client-react";
3	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Textarea } from "@/components/ui/textarea";
7	import { Skeleton } from "@/components/ui/skeleton";
8	import { Label } from "@/components/ui/label";
9	import { Plus, Edit2, Trash2, Users, Sparkles, Loader2, X } from "lucide-react";
10	import { useQueryClient } from "@tanstack/react-query";
11	import { Player } from "@workspace/api-client-react";
12	import { useToast } from "@/hooks/use-toast";
13	
14	interface PlayersProps {
15	  projectId: number;
16	}
17	
18	export function Players({ projectId }: PlayersProps) {
19	  const queryClient = useQueryClient();
20	  const { data: players, isLoading } = useListPlayers(projectId);
21	  const createPlayer = useCreatePlayer();
22	  const updatePlayer = useUpdatePlayer();
23	  const deletePlayer = useDeletePlayer();
24	  const enhancePlayer = useAiEnhancePlayer();
25	  const { toast } = useToast();
26	  const [enhancingId, setEnhancingId] = useState<number | null>(null);
27	
28	  const handleEnhance = async (playerId: number) => {
29	    setEnhancingId(playerId);
30	    try {
31	      await enhancePlayer.mutateAsync({ projectId, playerId });
32	      queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
33	      toast({ title: "Player enhanced", description: "AI tightened the profile." });
34	    } catch (err) {
35	      toast({ title: "Enhance failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
36	    } finally {
37	      setEnhancingId(null);
38	    }
39	  };
40	
41	  const [showAdd, setShowAdd] = useState(false);
42	  const [editPlayerId, setEditPlayerId] = useState<number | null>(null);
43	
44	  const [formData, setFormData] = useState({ name: "", role: "", description: "", strategy: "" });
45	
46	  const isFormOpen = showAdd || editPlayerId !== null;
47	  const isEditing = editPlayerId !== null;
48	
49	  const closeForm = () => {
50	    setShowAdd(false);
51	    setEditPlayerId(null);
52	    setFormData({ name: "", role: "", description: "", strategy: "" });
53	  };
54	
55	  const handleCreate = async () => {
56	    if (!formData.name) return;
57	    await createPlayer.mutateAsync({ projectId, data: formData });
58	    closeForm();
59	    queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
60	  };
61	
62	  const handleUpdate = async () => {
63	    if (!editPlayerId || !formData.name) return;
64	    await updatePlayer.mutateAsync({ projectId, playerId: editPlayerId, data: formData });
65	    closeForm();
66	    queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
67	  };
68	
69	  const handleDelete = async (id: number) => {
70	    await deletePlayer.mutateAsync({ projectId, playerId: id });
71	    queryClient.invalidateQueries({ queryKey: getListPlayersQueryKey(projectId) });
72	  };
73	
74	  const openAdd = () => {
75	    setEditPlayerId(null);
76	    setFormData({ name: "", role: "", description: "", strategy: "" });
77	    setShowAdd(true);
78	  };
79	
80	  const openEdit = (player: Player) => {
81	    setShowAdd(false);
82	    setFormData({
83	      name: player.name,
84	      role: player.role || "",
85	      description: player.description || "",
86	      strategy: player.strategy || ""
87	    });
88	    setEditPlayerId(player.id);
89	  };
90	
91	  return (
92	    <div className="space-y-8 pb-8">
93	      <div className="flex justify-between items-center">
94	        <h2 className="text-xl font-bold">Player Profiles</h2>
95	        {!isFormOpen && (
96	          <Button onClick={openAdd} data-testid="add-player-button">
97	            <Plus className="h-4 w-4 mr-2" /> Add Player
98	          </Button>
99	        )}
100	      </div>
101	
102	      {isFormOpen && (
103	        <Card className="bg-card border-primary/40" data-testid="player-form-panel">
104	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
105	            <CardTitle className="text-base">{isEditing ? "Edit Player Profile" : "Add Player Profile"}</CardTitle>
106	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={closeForm}><X className="h-4 w-4" /></Button>
107	          </CardHeader>
108	          <CardContent className="space-y-4">
109	            <div className="space-y-2"><Label>Name/Persona *</Label><Input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="e.g. The Aggressor" autoFocus /></div>
110	            <div className="space-y-2"><Label>Role</Label><Input value={formData.role} onChange={e => setFormData({...formData, role: e.target.value})} placeholder="e.g. Attacker, Support" /></div>
111	            <div className="space-y-2"><Label>Description</Label><Textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} /></div>
112	            <div className="space-y-2"><Label>Typical Strategy</Label><Textarea value={formData.strategy} onChange={e => setFormData({...formData, strategy: e.target.value})} /></div>
113	            <div className="flex justify-end gap-2 pt-2">
114	              <Button variant="outline" onClick={closeForm}>Cancel</Button>
115	              <Button onClick={isEditing ? handleUpdate : handleCreate} disabled={!formData.name}>
116	                {isEditing ? "Save Changes" : "Create"}
117	              </Button>
118	            </div>
119	          </CardContent>
120	        </Card>
121	      )}
122	
123	      {isLoading ? (
124	        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
125	          {[1,2,3].map(i => <Skeleton key={i} className="h-48 w-full" />)}
126	        </div>
127	      ) : players?.length === 0 ? (
128	        <div className="text-center py-16 border border-dashed border-border rounded-xl bg-card/50">
129	          <Users className="h-10 w-10 text-muted-foreground mx-auto mb-4" />
130	          <h3 className="text-lg font-medium">No players yet</h3>
131	          <p className="text-muted-foreground mt-1">Define player profiles and their typical strategies.</p>
