602	                <p className="text-sm text-white leading-relaxed bg-background/50 border border-border rounded-md p-3">
603	                  {enhance.description}
604	                </p>
605	              </div>
606	
607	              {/* Lore & Design Notes */}
608	              {(enhance.lore || enhance.designNotes) && (
609	                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
610	                  {enhance.lore && (
611	                    <div className="space-y-1">
612	                      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Flavor / Lore</p>
613	                      <p className="text-xs text-muted-foreground italic leading-relaxed bg-background/40 border border-border/50 rounded p-2.5">
614	                        "{enhance.lore}"
615	                      </p>
616	                    </div>
617	                  )}
618	                  {enhance.designNotes && (
619	                    <div className="space-y-1">
620	                      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Designer's Notes</p>
621	                      <p className="text-xs text-muted-foreground leading-relaxed bg-background/40 border border-border/50 rounded p-2.5">
622	                        {enhance.designNotes}
623	                      </p>
624	                    </div>
625	                  )}
626	                </div>
627	              )}
628	
629	              {/* Suggested Properties */}
630	              {enhance.suggestedProperties.length > 0 && (
631	                <div className="space-y-2">
632	                  <div className="flex items-center justify-between">
633	                    <p className={`text-xs font-semibold uppercase tracking-wider ${doc?.color ?? "text-primary"}`}>
634	                      Suggested Properties ({enhance.suggestedProperties.length})
635	                    </p>
636	                    <div className="flex gap-2 text-xs">
637	                      <button
638	                        className="text-primary hover:underline"
639	                        onClick={() => setSelectedProps(new Set(enhance.suggestedProperties.map((_, i) => i)))}
640	                      >
641	                        All
642	                      </button>
643	                      <button
644	                        className="text-muted-foreground hover:underline"
645	                        onClick={() => setSelectedProps(new Set())}
646	                      >
647	                        None
648	                      </button>
649	                    </div>
650	                  </div>
651	                  <div className="space-y-1.5">
652	                    {enhance.suggestedProperties.map((prop, i) => {
653	                      const isSelected = selectedProps.has(i);
654	                      return (
655	                        <div
656	                          key={i}
657	                          className={`flex items-start gap-2.5 p-2.5 rounded-md border cursor-pointer transition-colors ${
658	                            isSelected ? "border-primary/40 bg-primary/5" : "border-border bg-muted/10"
659	                          }`}
660	                          onClick={() => setSelectedProps((prev) => {
661	                            const next = new Set(prev);
662	                            if (next.has(i)) next.delete(i); else next.add(i);
663	                            return next;
664	                          })}
665	                        >
666	                          <div className={`w-4 h-4 rounded border-2 flex items-center justify-center shrink-0 mt-0.5 transition-colors ${
667	                            isSelected ? "border-primary bg-primary" : "border-border"
668	                          }`}>
669	                            {isSelected && <Check className="w-2.5 h-2.5 text-primary-foreground" />}
670	                          </div>
671	                          <div className="flex-1 min-w-0">
672	                            <div className="flex items-center gap-1.5 flex-wrap">
673	                              <code className="text-white text-xs font-mono">{prop.name}</code>
674	                              <Badge variant="outline" className="text-[10px] font-mono bg-secondary/30">{prop.dataType}</Badge>
675	                              {prop.defaultValue != null && prop.defaultValue !== "" && (
676	                                <span className="text-xs text-muted-foreground font-mono">= {prop.defaultValue}</span>
677	                              )}
678	                            </div>
679	                            {prop.reason && (
680	                              <p className="text-xs text-muted-foreground mt-0.5">{prop.reason}</p>
681	                            )}
682	                          </div>
683	                        </div>
684	                      );
685	                    })}
686	                  </div>
687	                </div>
688	              )}
689	
690	              {/* Action buttons */}
691	              <div className="flex items-center gap-2 pt-1 flex-wrap">
692	                <Button
693	                  onClick={handleApply}
694	                  disabled={applying || applied}
695	                  size="sm"
696	                  className="bg-primary text-primary-foreground"
697	                  data-testid={`apply-enhance-${entity.id}`}
698	                >
699	                  {applied
700	                    ? <><Check className="w-3.5 h-3.5 mr-1.5" />Applied!</>
701	                    : applying
702	                    ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1.5" />Applying…</>
703	                    : <><Wand2 className="w-3.5 h-3.5 mr-1.5" />Apply Description{selectedProps.size > 0 ? ` + ${selectedProps.size} ${selectedProps.size === 1 ? "Property" : "Properties"}` : ""}</>}
704	                </Button>
705	                <Button
706	                  onClick={handleEnhance}
707	                  disabled={isEnhancing}
708	                  size="sm"
709	                  variant="outline"
710	                  className="text-muted-foreground border-border hover:text-white"
711	                >
712	                  <Sparkles className="w-3.5 h-3.5 mr-1.5" />
713	                  Regenerate
714	                </Button>
715	                <Button
716	                  onClick={() => setShowEnhance(false)}
717	                  size="sm"
718	                  variant="ghost"
719	                  className="text-muted-foreground hover:text-white ml-auto"
720	                >
721	                  Dismiss
722	                </Button>
723	              </div>
724	            </div>
725	          )}
726	        </div>
727	      )}
728	
729	      {/* Expanded panel — lore / design notes / properties */}
730	      {isExpanded && (
731	        <div className="px-5 py-4 border-t border-border bg-muted/5 space-y-4">
732	          {(entity.lore || entity.designNotes) && (
733	            <div
734	              className="grid grid-cols-1 md:grid-cols-2 gap-3"
735	              data-testid={`entity-meta-${entity.id}`}
736	            >
737	              {entity.lore && (
738	                <div className="space-y-1">
739	                  <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
740	                    Flavor / Lore
741	                  </p>
742	                  <p
743	                    className="text-xs text-muted-foreground italic leading-relaxed bg-background/40 border border-border/50 rounded p-2.5 whitespace-pre-wrap"
744	                    data-testid={`entity-lore-${entity.id}`}
745	                  >
746	                    "{entity.lore}"
747	                  </p>
748	                </div>
749	              )}
750	              {entity.designNotes && (
751	                <div className="space-y-1">
752	                  <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
753	                    Designer's Notes
754	                  </p>
755	                  <p
756	                    className="text-xs text-muted-foreground leading-relaxed bg-background/40 border border-border/50 rounded p-2.5 whitespace-pre-wrap"
757	                    data-testid={`entity-design-notes-${entity.id}`}
758	                  >
759	                    {entity.designNotes}
760	                  </p>
761	                </div>
762	              )}
763	            </div>
764	          )}
765	          <EntityProperties projectId={projectId} entityId={entity.id} />
766	        </div>
767	      )}
768	    </Card>
769	  );
770	}
