772	// ════════════════════════════════════════════════════════════════════════════
773	// Entity Properties sub-component — table with inline editing + add row form
774	// ════════════════════════════════════════════════════════════════════════════
775	const PROP_TYPES = ["number", "string", "boolean", "enum"] as const;
776	
777	function EntityProperties({ projectId, entityId }: { projectId: number; entityId: number }) {
778	  const queryClient = useQueryClient();
779	  const { data: properties, isLoading } = useListEntityProperties(projectId, entityId);
780	  const createProperty = useCreateEntityProperty();
781	  const updateProperty = useUpdateEntityProperty();
782	  const deleteProperty = useDeleteEntityProperty();
783	  const { toast } = useToast();
784	
785	  const [newProp, setNewProp] = useState({ name: "", dataType: "number", defaultValue: "" });
786	  const [editingId, setEditingId] = useState<number | null>(null);
787	  const [editProp, setEditProp] = useState({ name: "", dataType: "number", defaultValue: "" });
788	
789	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
790	
791	  const refresh = () =>
792	    queryClient.invalidateQueries({ queryKey: getListEntityPropertiesQueryKey(projectId, entityId) });
793	
794	  // Convert string input → backend payload (numeric → defaultValue, else textValue)
795	  const valueToPayload = (val: string): { defaultValue?: number; textValue?: string } => {
796	    if (val === "") return { textValue: "" };
797	    const num = Number(val);
798	    if (Number.isFinite(num) && val.trim() !== "") return { defaultValue: num, textValue: "" };
799	    return { textValue: val, defaultValue: undefined };
800	  };
801	
802	  // Display the most relevant column value
803	  const displayValue = (p: EntityProperty): string => {
804	    if (p.defaultValue != null) return String(p.defaultValue);
805	    if (p.textValue) return p.textValue;
806	    if (p.value != null) return String(p.value);
807	    return "—";
808	  };
809	
810	  const handleAddProp = async (e: React.FormEvent) => {
811	    e.preventDefault();
812	    if (!newProp.name) return;
813	    try {
814	      const payload = {
815	        name: newProp.name,
816	        dataType: newProp.dataType,
817	        ...valueToPayload(newProp.defaultValue),
818	      };
819	      await createProperty.mutateAsync({ projectId, entityId, data: payload });
820	      setNewProp({ name: "", dataType: "number", defaultValue: "" });
821	      refresh();
822	    } catch (err) {
823	      toast({ title: "Could not add property", description: errMsg(err), variant: "destructive" });
824	    }
825	  };
826	
827	  const startEdit = (prop: EntityProperty) => {
828	    setEditingId(prop.id);
829	    setEditProp({
830	      name: prop.name,
831	      dataType: prop.dataType,
832	      defaultValue: displayValue(prop) === "—" ? "" : displayValue(prop),
833	    });
834	  };
835	
836	  const saveEdit = async () => {
837	    if (!editingId) return;
838	    try {
839	      const payload = {
840	        name: editProp.name,
841	        dataType: editProp.dataType,
842	        ...valueToPayload(editProp.defaultValue),
843	      };
844	      await updateProperty.mutateAsync({ projectId, entityId, propertyId: editingId, data: payload });
845	      setEditingId(null);
846	      refresh();
847	    } catch (err) {
848	      toast({ title: "Could not update property", description: errMsg(err), variant: "destructive" });
849	    }
850	  };
851	
852	  const handleDelete = async (id: number) => {
853	    try {
854	      await deleteProperty.mutateAsync({ projectId, entityId, propertyId: id });
855	      refresh();
856	    } catch (err) {
857	      toast({ title: "Could not delete property", description: errMsg(err), variant: "destructive" });
858	    }
859	  };
860	
861	  if (isLoading) {
862	    return <div className="text-sm text-muted-foreground py-1">Loading properties…</div>;
863	  }
864	
865	  return (
866	    <div className="space-y-3">
867	      <div className="flex items-center gap-2 text-xs font-semibold text-muted-foreground uppercase tracking-wider">
868	        <Settings className="w-3.5 h-3.5" /> Properties
869	        {properties && properties.length > 0 && (
870	          <span className="text-muted-foreground/50 font-normal normal-case tracking-normal ml-1">
871	            — click row to edit
872	          </span>
873	        )}
874	      </div>
875	
876	      {properties && properties.length > 0 && (
877	        <div className="rounded-md border border-border overflow-hidden">
878	          <div className="grid grid-cols-12 gap-3 px-3 py-2 text-[10px] font-semibold text-muted-foreground uppercase tracking-wider bg-muted/20 border-b border-border">
879	            <div className="col-span-4">Name</div>
880	            <div className="col-span-3">Type</div>
881	            <div className="col-span-3">Default</div>
882	            <div className="col-span-2" />
883	          </div>
884	          {properties.map((prop) => (
885	            <div key={prop.id} className="border-b border-border/40 last:border-0">
886	              {editingId === prop.id ? (
887	                <div className="grid grid-cols-12 gap-2 px-3 py-2 items-center bg-primary/5 border-l-2 border-primary">
888	                  <div className="col-span-4">
889	                    <Input
890	                      value={editProp.name}
891	                      onChange={(e) => setEditProp((p) => ({ ...p, name: e.target.value }))}
892	                      className="h-7 text-xs bg-input font-mono"
893	                      autoFocus
894	                    />
895	                  </div>
896	                  <div className="col-span-3">
897	                    <Select value={editProp.dataType} onValueChange={(v) => setEditProp((p) => ({ ...p, dataType: v }))}>
898	                      <SelectTrigger className="h-7 text-xs bg-input"><SelectValue /></SelectTrigger>
899	                      <SelectContent>
900	                        {PROP_TYPES.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
901	                      </SelectContent>
902	                    </Select>
903	                  </div>
904	                  <div className="col-span-3">
905	                    <Input
906	                      value={editProp.defaultValue}
907	                      onChange={(e) => setEditProp((p) => ({ ...p, defaultValue: e.target.value }))}
908	                      className="h-7 text-xs bg-input font-mono"
909	                      placeholder="default"
910	                    />
911	                  </div>
912	                  <div className="col-span-2 flex items-center justify-end gap-1">
913	                    <button
914	                      onClick={saveEdit}
915	                      disabled={updateProperty.isPending}
916	                      className="text-primary hover:text-primary/80 transition-colors p-1 disabled:opacity-50"
917	                      title="Save"
918	                    >
919	                      {updateProperty.isPending
920	                        ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
921	                        : <Check className="w-3.5 h-3.5" />}
922	                    </button>
923	                    <button
924	                      onClick={() => setEditingId(null)}
925	                      className="text-muted-foreground hover:text-white transition-colors p-1"
926	                      title="Cancel"
927	                    >
928	                      <X className="w-3.5 h-3.5" />
929	                    </button>
930	                  </div>
931	                </div>
932	              ) : (
933	                <div
934	                  className="grid grid-cols-12 gap-3 px-3 py-2 items-center text-sm hover:bg-muted/10 cursor-pointer group"
935	                  onClick={() => startEdit(prop)}
936	                  data-testid={`prop-row-${prop.id}`}
937	                >
938	                  <div className="col-span-4 font-mono text-xs text-white truncate">{prop.name}</div>
939	                  <div className="col-span-3">
940	                    <Badge variant="secondary" className="bg-secondary/40 font-mono text-[10px]">{prop.dataType}</Badge>
941	                  </div>
942	                  <div className="col-span-3 text-muted-foreground font-mono text-xs truncate">{displayValue(prop)}</div>
943	                  <div className="col-span-2 flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
944	                    <button
945	                      onClick={(e) => { e.stopPropagation(); startEdit(prop); }}
946	                      className="text-muted-foreground hover:text-white transition-colors p-0.5"
947	                      title="Edit"
948	                    >
949	                      <Pencil className="w-3 h-3" />
950	                    </button>
951	                    <button
952	                      onClick={(e) => { e.stopPropagation(); handleDelete(prop.id); }}
953	                      className="text-muted-foreground hover:text-destructive transition-colors p-0.5"
954	                      title="Delete"
955	                    >
956	                      <Trash2 className="w-3 h-3" />
957	                    </button>
958	                  </div>
959	                </div>
960	              )}
961	            </div>
962	          ))}
963	        </div>
964	      )}
965	
966	      {(!properties || properties.length === 0) && (
967	        <p className="text-xs text-muted-foreground/60 py-1">
968	          No properties yet. Add one below or use AI Enhance to get suggestions.
969	        </p>
970	      )}
971	
972	      <form onSubmit={handleAddProp} className="flex gap-2 items-end">
973	        <div className="flex-1 space-y-1">
974	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Property Name</Label>
975	          <Input
976	            className="h-8 text-xs bg-input font-mono"
977	            placeholder="property_name"
978	            value={newProp.name}
979	            onChange={(e) => setNewProp({ ...newProp, name: e.target.value })}
980	            data-testid={`prop-input-name-${entityId}`}
981	          />
982	        </div>
983	        <div className="w-32 space-y-1">
984	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Type</Label>
985	          <Select value={newProp.dataType} onValueChange={(v) => setNewProp({ ...newProp, dataType: v })}>
986	            <SelectTrigger className="h-8 text-xs bg-input"><SelectValue /></SelectTrigger>
987	            <SelectContent>
988	              {PROP_TYPES.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
989	            </SelectContent>
990	          </Select>
991	        </div>
992	        <div className="w-32 space-y-1">
993	          <Label className="text-[10px] text-muted-foreground uppercase tracking-wider">Default</Label>
994	          <Input
995	            className="h-8 text-xs bg-input font-mono"
996	            placeholder="0"
997	            value={newProp.defaultValue}
998	            onChange={(e) => setNewProp({ ...newProp, defaultValue: e.target.value })}
999	          />
1000	        </div>
1001	        <Button size="sm" className="h-8 shrink-0" type="submit" disabled={createProperty.isPending || !newProp.name}>
1002	          {createProperty.isPending
1003	            ? <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" />
1004	            : <Plus className="w-3.5 h-3.5 mr-1" />}
1005	          Add
1006	        </Button>
1007	      </form>
1008	    </div>
1009	  );
1010	}
